css:
html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: none;

  background: transparent !important;
  pointer-events: none;
}

.motor-widget,
.motor-widget * {
  box-sizing: border-box;
  pointer-events: none;
}

.motor-widget {
  --motor-border: #01524F;

  /* Estado inicial: rojo. */
  --motor-fill-light: #F3C6C2;
  --motor-fill-middle: #E69A93;
  --motor-fill-base: #D87971;

  position: relative;
  display: block;

  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;

  background: transparent;
  opacity: var(--w-opacity, 1);
  user-select: none;
}

/* BOOL = 0 */
.motor-widget[data-state="0"] {
  --motor-fill-light: #F3C6C2;
  --motor-fill-middle: #E69A93;
  --motor-fill-base: #D87971;
}

/* BOOL = 1: verde más claro y distinto al botón original. */
.motor-widget[data-state="1"] {
  --motor-fill-light: #F1FAEC;
  --motor-fill-middle: #DDF1CF;
  --motor-fill-base: #CCE7BB;
}

.motor-svg {
  display: block;

  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent;
  shape-rendering: geometricPrecision;
}

.motor-fill-light {
  stop-color: var(--motor-fill-light);
}

.motor-fill-middle {
  stop-color: var(--motor-fill-middle);
}

.motor-fill-base {
  stop-color: var(--motor-fill-base);
}

.motor-body {
  fill: url("#motor-surface");
  stroke: var(--motor-border);
  stroke-width: 6;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.motor-divider {
  fill: none;
  stroke: var(--motor-border);
  stroke-width: 3;
  stroke-linecap: round;
  opacity: 0.85;
}

.motor-lines {
  fill: none;
  stroke: var(--motor-border);
  stroke-width: 5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.motor-highlight {
  fill: none;
  stroke: #FFFFFF;
  stroke-width: 2.5;
  stroke-linecap: round;
  opacity: 0.65;
}

.motor-inner-shadow {
  fill: none;
  stroke: #01524F;
  stroke-width: 7;
  stroke-linecap: round;
  opacity: 0.12;
}

js:
"use strict";

(function () {
  let container = null;
  let latestWidget = window.WIDGET || {};

  function isActive(value) {
    if (value === true || value === 1) {
      return true;
    }

    if (typeof value === "string") {
      const normalized = value.trim().toLowerCase();

      return (
        normalized === "1" ||
        normalized === "true"
      );
    }

    // Sin dato o valor no reconocido: rojo.
    return false;
  }

  function render(widget) {
    if (!container) {
      return;
    }

    const state = isActive(widget.value) ? "1" : "0";

    container.setAttribute("data-state", state);
    container.setAttribute(
      "aria-label",
      "Motor: estado " + state
    );
  }

  window.onWidgetUpdate = function (widget) {
    latestWidget = widget || {};
    render(latestWidget);
  };

  function initialize() {
    container = document.querySelector(".motor-widget");

    render(latestWidget);
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
